  "{0} artık senin tımarın. Vergisi her gün kesene girecek; garnizonunu da sen kuracaksın.<br><br> Toprağı gözü olan lordlar bu karardan hoşlanmadı (−2 ilişki).": "{0} is your fief now. Its taxes come into your purse every day, and its garrison is yours to raise.<br><br> The lords who had their eye on that land did not care for the decision (−2 relation).",
  "{0} bilendi: {1} savaş boyunca +%{2} hasar, her savaşta biraz körelir.": "{0} sharpened: +{2}% damage for {1} battles, a little duller after each.",
