  "-{0} nam — <i>böyle bir düşmana yenilmek dilden dile dolaşacak.": "-{0} renown — <i>losing to an enemy like that will be told and retold.",
  "/ {0} hedef": "/ {0} target",
  "<b>{0}</b> köyüne gir ve mektubu bul, sonra <b>{1}</b> götür": "Enter <b>{0}</b> and find the letter, then carry it to <b>{1}</b>",
  "<b>{0}</b> köyüne gir, <b>🔥 Köyü Yağmala</b> de ve sayaç dolana kadar dayan (yakındaki lordlar dumanı görüp üstüne gelir; namın düşer)": "Enter <b>{0}</b>, choose <b>🔥 Raid the Village</b> and hold out until the counter fills (nearby lords see the smoke and ride in; your renown drops)",
  "<b>{0}</b> köyüne gir, çantanda <b>{1}/{2}</b> birim yemek olsun (buğday/ekmek/et/peynir sayılır; grubun her gün yediği için erken varmak iyidir)": "Enter <b>{0}</b> carrying <b>{1}/{2}</b> units of food (wheat/bread/meat/cheese count; your party eats daily, so arrive early)",
  "<b>{0}</b> köyünün yakınında (yarım günlük mesafede) bekle; çapulcular gelince savaş — <b>{1}/{2}</b> dalga püskürtüldü": "Wait near <b>{0}</b> (within half a day's ride); fight the raiders when they come — <b>{1}/{2}</b> waves thrown back",
  "<b>{0}</b> pazarından peynir al — <b>{1}/{2}</b> birim (başka şehirde alınanı saymaz)": "Buy cheese at <b>{0}</b>'s market — <b>{1}/{2}</b> units (what you buy elsewhere doesn't count)",
  "<b>{0}</b> gir ve avluda tavuk kovala — 15 saniyede 8 tavuk. Kaçırırsan süre dolana kadar yeniden deneyebilirsin.": "Enter <b>{0}</b> and chase chickens in the yard — 8 birds in 15 seconds. Miss it and you can try again until the deadline.",
  "<b>{0}</b> gir, çantanda <b>{1}/{2}</b> birim {3} olsun (herhangi bir şehrin pazarından alınır)": "Enter <b>{0}</b> carrying <b>{1}/{2}</b> units of {3} (buy it at any town's market)",
  "{0} tuttu.": "{0} came out right.",
  "Örs": "Anvil",
  "Örse al": "To the anvil",
  "çekiç": "hammer",
  "İyi iş": "Good work",
  "Şekil": "Shape",
  "Şekil tuttu. Baştan uca kiraz-turuncuyken su ver; uç kararmadan.": "The shape holds. Quench it while it is cherry-orange end to end, before the tip goes dark.",
  "Şu an keskin: +%{0} hasar": "Sharp now: +{0}% damage",
  "← Ocağa dön": "← Back to the forge",
