  "❔ Nasıl bilenir?": "❔ How do you sharpen?",
  "❔ Nasıl dövülür?": "❔ How to forge",
  "🏆 işaretli bir şehrin arenasına çık ve <b>{0}-{1}</b> skorla elen. Kazanırsan da erken elenirsen de görev yanar.": "Enter the arena in a town marked 🏆 and go out with a score of <b>{0}-{1}</b>. Winning — or falling early — burns the quest.",
  "🏘️ Şehre dön": "🏘️ Back to town",
