  "🏰 {0} {1} adına tımar oldu.": "🏰 {0} has become a fief in {1}'s name.",
  "👑 Haraca bağladığın köyler": "👑 Villages paying you tribute",
  "💞 Eşinle vakit geçir": "💞 Spend time with your spouse",
