  "Eyvah Anam! 😱": "Mother Help Us! 😱",
  "Eğitim": "Trainer",
  "Fetihlerinden ve namından bahset": "Talk of conquests and renown",
  "Fidye İsteği": "Ransom demand",
  "Gaius": "Gaius",
  "Ganimetten ve zenginlikten bahset": "Talk of loot and riches",
  "Garnizon": "Garrison",
  "Garnizon bırakmazsan düşman ilk fırsatta geri alır (yerleşim ekranı → 🛡️ Garnizon).": "Leave no garrison and the enemy takes it back at the first chance (settlement screen → 🛡️ Garrison).",
  "Garnizon: <b>{0}</b> asker": "Garrison: <b>{0}</b> men",
  "Garnizon: ~{0} asker": "Garrison: ~{0} troops",
  "Garnizonsuz bıraktığın tımar bir gün bile dayanmadı.": "The fief you left without a garrison didn't last a single day.",
  "Gece": "Night",
  "Gece yürüyüşü": "Night march",
  "Gecikmedi, faizle bekliyor. Bana teşekkür edeceksin.": "It isn't late, it's waiting with interest. You'll thank me.",
  "Gecikmiş maaş": "Overdue wages",
  "Gel bakalım! Otur şöyle. Senin geldiğin gün kötü haber gelmez bu kapıya.": "Come in! Sit down. No bad news comes through this door on a day you do.",
  "Gel gel! Şu peyniri dene, kokusu ağır ama karakteri var — sana benziyor.": "Come, come! Try this cheese — heavy on the nose but full of character. Rather like you.",
  "Gel şöyle. Kılıcını duvara as, sohbet uzun sürebilir.": "Come here. Hang your sword on the wall; this may take a while.",
  "Gelişimi: {0}": "Grows with: {0}",
