  "Terk Edilmiş Kamp": "Abandoned Camp",
  "Terk Edilmiş Çiftlik": "Abandoned Farm",
  "Teslim oldun! Birliğini kaybettin.": "You surrendered! You lost your company.",
  "Teslim oldun! Tüm birliğini kaybettin ve köle olarak sürükleneceksin.<br>-{0} Dinar": "You surrendered! You lost your whole company and will be dragged off as a slave.<br>-{0} denars",
  "Teşrifatçı adını biliyor — fazlasıyla. \"{0} birini bu salona sokamam.\" ": "The usher knows your name — all too well.\n\"I cannot let {0} into this hall.\"\n\n",
  "Ticaret": "Trade",
  "Tokatlıyoruz! 😎": "We're Winning! 😎",
  "Topal Rıza": "Limping Rıza",
  "Toplam": "Total",
  "Toprak Yol": "Dirt Road",
  "Toprak iyidir de, faiz uyumuyor. Ben de uyumuyorum; ikimiz anlaşıyoruz.": "Land is good, but interest never sleeps. Neither do I; we get along.",
  "Toprak sahibi": "Landholder",
  "Toprağı olmayan krala kimse yemin etmez. Önce bir şehir ya da kale fethet — vassal ancak tımar karşılığı gelir.": "Nobody swears to a landless king. Take a town or a castle first — a vassal comes only for a fief.",
  "Topuz ve Kalkan": "Mace and Shield",
  "Turgut": "Turgut",
  "Turnuva şampiyonu": "Tournament Champion",
  "Turnuvalar eskisi gibi değil. Eskiden adam ölürdü, şimdi herkes sağ dönüyor.": "Tournaments aren't what they were. Men used to die; now everyone rides home alive.",
  "Turnuvayı kazandın! +500 Dinar, +20 Nam": "You won the tournament! +500 denars, +20 renown",
  "Tut: {0} kişi ({1} Dinar)": "Hire {0} ({1} denars)",
  "Tüccar boş ranzalarını gösteriyor: \"Zincirim bol, malın yok. Git birkaç çapulcu topla da konuşalım.\"": "The trader gestures at his empty bunks: \"I've chains to spare and you've no goods. Go round up a few looters and then we'll talk.\"",
  "Tüccar esirlerini tek tek süzüyor.": "The trader looks your prisoners over one by one.",
  "Tüccar soylulara elini sürmez: \"Onların fidyesi benim değil, senin işin.\" (Grup ekranından fidye iste)": "The trader will not touch nobles: \"Their ransom is your business, not mine.\" (Demand it from the party screen)",
  "Tüm tımarlarının garnizonu: {0} asker · {1} dinar/gün": "Garrisons across all your fiefs: {0} troops · {1} denars/day",
  "Tür: {0}{1}{2}{3}": "Type: {0}{1}{2}{3}",
  "Tımar geliri": "Fief income",
  "Tımar vassalın olur; vergisinin %{0} haraç olarak sana gelir. Buradaki <b>{1}</b> asker onun emrine geçer.": "The fief becomes your vassal's; {0}% of its tax comes to you as tribute. The <b>{1}</b> troops here pass to his command.",
  "Tımar vergisi": "Fief taxes",
  "Ufukta kimse yok. Ambarı boşalt.": "Nobody on the horizon. Empty the granary.",
  "Ufukta kıpırdayan bir şey yok. Boşuna tırmandın.": "Nothing stirs on the horizon. You climbed up for nothing.",
  "Ulaşılan en yüksek": "Highest reached",
  "Uzaklaş": "Move away",
  "Üstlendiğin bir görev yok. İki kapı var:<br> • Bir şehrin ya da kalenin <b>Lordlar Salonu</b>'na gir, bir soyluyla konuş ve \"Bana bir iş var mı?\" de — mizacı ve sana olan ilişkisi hangi işi teklif edeceğini belirler.<br> • Bir şehrin <b>hanı</b>nda lonca ustasıyla konuş — ilişki istemez, para öder.": "You have no quest. There are two doors:<br> • Walk into the <b>Lords' Hall</b> of a town or castle, talk to a noble and ask \"Do you have work for me?\" — their temper and their relation with you decide what they offer.<br> • Talk to the guild master in a town's <b>tavern</b> — he asks for no relation and pays in coin.",
  "Vaktim paradır. Sen ise şu ana kadar bedavaya konuşuyorsun.": "My time is money. So far you've been talking for free.",
  "Vasisi": "Her guardian",
  "Vazgeç": "Give up",
  "Verecek bir şeyin yok.": "You have nothing to give.",
  "Veren: {0}": "Given by: {0}",
  "Veren: {0} · {1}. güne kadar": "From: {0} · due by day {1}",
  "Vergi": "Tax",
  "Vergiyi ödemeyen iki köylüyü kuleye astım. Üçüncüsü ödedi. Sistem işliyor.": "I hanged two peasants from the tower for not paying. The third paid. The system works.",
  "WASD hareket · Sol tık saldırı": "WASD to move · left click to attack",
