  "Yalan Haber": "False Word",
  "Yalan tuttu. Ama artık {0} lordları da sana doğruyu söylemiyor (5 gün).": "The lie held. But now the lords of {0} won't tell you the truth either (5 days).",
  "Yanlış konu açarsan geri teper.": "Raise the wrong subject and it backfires.",
  "Yanında asker yok.": "You have no troops with you.",
  "Yanındakiler": "Carried with you",
  "Yaralı Asker": "Wounded Soldier",
  "Yararlı adamları severim. Yararsızlara ne yaptığımı köylülere sorabilirsin.": "I like useful men. Ask the peasants what I do with the useless ones.",
  "Yaratık sürüsü": "Beast pack",
