  "Yay": "Bow",
  "Yaya savaş hızı {0}": "On-foot combat speed {0}",
  "Yaydığın dedikodu geri tepti. Kimin uydurduğu anlaşıldı. {0} bütün lordlarıyla −25 ilişki, −10 ilgi.": "The rumor you spread backfired. They worked out who invented it.\n−25 relation with every lord of {0}, −10 affection.",
  "Yaz. Silmesi kolay olur.": "Write it down. It'll be easy to erase.",
  "Yazılamadı: ": "Could not write: ",
  "Yağma": "Looting",
  "Yağmayı bıraktın. Ambara dokunmadan çekildin — köylü ucuz kurtuldu.": "You called off the raid. You pulled back without touching the granary — the villagers got off lightly.",
  "Yaşlı çavuş": "Old Sergeant",
  "Yemek hazır efendim.": "Dinner is served, my lord.",
  "Yemek molasından önce şunları halledelim! {0} önden git, {1} destek çık!": "Let's finish this lot before the meal break! {0}, take the front; {1}, back him up!",
  "Yemek çeşidi": "Food variety",
  "Yeminimi bozduğumu söyleyene rastlarsan bana getir. Yüzleşmeyi severim.": "If you meet anyone who says I broke my oath, bring him to me. I enjoy a confrontation.",
  "Yeminli": "Sworn Man",
  "Yeni bir yüz! Çavuşum yine kaybedecek, ben hep yeni yüzlere bahse girerim.": "A new face! My sergeant will lose again — I always bet on new faces.",
  "Yenildin! Esir düştün! Tüm birliğin dağıldı.<br>-{0} Dinar": "You were beaten! You are a prisoner! Your whole company is scattered.<br>-{0} denars",
  "Yerleşim dağıtımı 12 denemede kurallara oturmadı:": "Yerleşim dağıtımı 12 denemede kurallara oturmadı:",
