  "Yol Bulma": "Pathfinding",
  "Yol kenarındaki çalılıkta unutulmuş bir kese buldun. Sahibi aramaya gelmedi.<br><b>+{0} dinar": "You found a forgotten purse in the roadside brush. Its owner never came looking.<br><b>+{0} denars",
  "Yol temiz — şimdi <b>{0}</b> gir ve loncanın adamına haber ver": "The road is clear — now enter <b>{0}</b> and report to the guild's man",
  "Yolda başıboş dolaşan bir <b>{0}</b> gruba katıldı. Eski komutanını sormamak en iyisi.": "A <b>{0}</b> wandering the road joined your party. Best not to ask about his old commander.",
  "Yolda duyduğun söylenti: \"<i>{0} esnafı adamı donuna kadar soyar</i>.\" Cüzdanını sıkı tut.": "A rumour you picked up on the road: \"<i>The traders of {0} will strip a man to his drawers</i>.\" Keep a tight hold on your purse.",
  "Yollarda gezen çok, iş bitiren az. Sen hangisisin?": "Many wander the roads, few finish anything. Which are you?",
  "Yöntem:": "Method:",
  "Yük Ganimeti:": "Cargo plunder:",
