  "Yük: {0}{1}": "Cargo: {0}{1}",
  "Yükle": "Load",
  "Yüksek tazeleme hızlı ekranda fazla kareyi atar. Ölçülen:": "Drops surplus frames on a high-refresh display. Measured:",
  "Yüzü buz kesti. \"Sen beni hiç dinlememişsin,\" dedi ve arkasını döndü.": "Her face turned to ice. \"You have never listened to me,\" she said, and turned away.",
  "Yüzünü görmek bile keyfimi kaçırıyor. Çabuk söyle derdini.": "The sight of your face alone sours my mood. Say your piece and be quick.",
  "Yıllar önce nöbet tutulan bir kule. Merdiveni hâlâ sağlam görünüyor.": "A tower once kept under watch. Its stairs still look sound.",
  "Zalim": "Cruel",
  "Zaman akışı": "Time flow",
  "Zaman yalnızca haritada, sen yol alırken işler. Gece yol alma hızı −%15, görüş ×0.7. Rozete tıkla → akış hızını değiştir.": "Time only passes on the map while you travel. At night travel speed is −15% and sight ×0.7. Click the badge to change the flow of time.",
  "Zaten evlisin. Kalradya buna hoş bakmaz.": "You're already married. Calradia frowns on that.",
  "Zekâ": "Intelligence",
  "Zengin": "Rich",
  "Zengin adamla konuşmak bedava. Bu benim tek indirimim.": "Talking to a rich man is free. That is my only discount.",
  "Zincir Pazarı": "The Chain Market",
  "Zincirdeki Kardeş": "The Brother in Chains",
  "Zincirdeki tek esir sensin.": "You are the only one in chains.",
  "Zincirlerin boş. Kazandığın savaşlarda düşen düşmanların bir kısmı esir alınır; şehirdeki köle tüccarına satılır.": "Your chains are empty. Some of the enemies who fall in battles you win are taken prisoner; they can be sold to the slave trader in town.",
  "Zindandan kardeşiyle beraber çıktın. Lord bunu ömrü boyunca unutmayacak. (+10 ekstra ilişki, +15 ekstra nam)": "You walked out of the dungeon with his brother. The lord will not forget it as long as he lives.\n(+10 extra relation, +15 extra renown)",
  "Zindanım dolu ama bir kişilik yer her zaman açılır. Sen ne diyordun?": "My dungeon is full, but room for one more can always be found. You were saying?",
