  "{0} Dinar ödedin. Zincirlerin çözüldü.": "You paid {0} denars. Your chains came off.",
  "{0} Düşman": "{0} Enemies",
  "{0} Hesabı": "The reckoning for {0}",
  "{0} Kervanı": "{0} Caravan",
  "{0} Köylüleri": "{0} Villagers",
  "{0} Nişanlandınız! Düğün {1} gün sonra {2} şehrindeki şölende yapılacak. O gün orada ol.": "{0}\n\nYou are betrothed! The wedding will be held at the feast in {2} in {1} days. Be there on the day.",
  "{0} Ozan üç kez tekrarlattı. Artık ezberinde.": "{0}\n\nThe bard made you repeat it three times. You know it by heart now.",
  "{0} adın buraya da ulaşmış: fazladan gönüllü çıktı, ücreti de kırdılar (+%{1} gönüllü, −%{2} ücret).": "Your name as {0} has reached here too: extra volunteers came forward and they cut their price (+{1}% volunteers, −{2}% fee).",
  "{0} artık {1} tımarı. +20 ilişki{2}. Günlük haracı: +{3} dinar.": "{0} is now {1}'s fief.\n+20 relations{2}.\nDaily tribute: +{3} denars.",
  "{0} birim ({1} tahıl/ekmek · {2} et/peynir)": "{0} units ({1} grain/bread · {2} meat/cheese)",
  "{0} birim et/peynir": "{0} units of meat/cheese",
  "{0} damgası: köyün yarısı seni görünce ambara saklandı (gönüllü −%{1}, ücret ×{2}).": "The {0} brand: half the village hid in the barn at the sight of you (volunteers −{1}%, fee ×{2}).",
  "{0} dinar": "{0} denars",
  "{0} dinar · {1} saattir": "{0} denars · for {1} hours",
  "{0} diye biliniyorsun — köy yakan adamın sözü bu salonda hiç geçmez.": "You are known as {0} — a village-burner's word carries no weight in this hall.",
  "{0} diye biliniyorsun — köy yakan adamın sözü bu salonda zor geçer.": "You are known as {0} — a village-burner's word carries little weight in this hall.",
  "{0} dizlerinin üstüne çöktü ve kılıcını bıraktı. \"Bu iş burada bitti,\" dedi ve salonu terk etti. +15 ilgi, +10 nam, {1} ile −25 ilişki.": "{0} dropped to his knees and let go of his sword.\n\"This ends here,\" he said, and left the hall.\n\n+15 affection, +10 renown, −25 relation with {1}.",
  "{0} doğdu! Artık maaş istemez, yemek yemez ve muazzam güçlü!": "{0} is born! No wages, no food, and monstrously strong!",
  "{0} dumanı görüp yetişti — yağma yarıda kaldı, ganimet yok.": "{0} saw the smoke and arrived in time — the raid was cut short, no loot.",
  "{0} esir salıverildi.": "{0} prisoners released.",
  "{0} esir satıldı. +{1} dinar.": "{0} prisoners sold. +{1} denars.",
  "{0} fethedildi — kendi krallığını ilan ettin!": "{0} has been taken — you have declared your own kingdom!",
  "{0} fethedildi!</b> {1} adına aldın; kralın burayı sana tımar verdi.": "{0} has been taken!</b> You took it in the name of {1}; your king has granted it to you as a fief.",
  "{0} gruba katıldı. {1} yeteneği artık grubuna işliyor (seviye {2}).": "{0} joined the party. Their {1} skill now benefits your whole party (level {2}).",
  "{0} grubundayken katılmaz": "will not join while {0} is in the party",
