  "{0} ile aran ({1}) sayesinde:": "Thanks to your standing with {0} ({1}):",
  "{0} ile ilişki": "relation with {0}",
  "{0} için {1} dinar fidye alındı. Serbest bıraktın ama bunu unutmayacak.": "You took {1} denars in ransom for {0}. You set them free, but they won't forget this.",
  "{0} kalmadı — pazarın stoku tükendi, birkaç gün sonra gel.": "No {0} left — the market is out of stock, come back in a few days.",
  "{0} kişilik garnizonun kılıçtan geçti.": "Your garrison of {0} was put to the sword.",
  "{0} kumun üstünde kaldı, kalabalık ıslık çalıyor.": "{0} is left lying in the sand and the crowd is whistling.",
  "{0} kuşatma altında.": "{0} is under siege.",
  "{0} köyünden bir kadın \"yoldan geçene uğur olsun\" deyip iki peynir bıraktı.<br><b>+2 peynir</b>, moral": "A woman from the village of {0} left two cheeses, saying \"a blessing on the passing traveller\".<br><b>+2 cheese</b>, morale",
  "{0} lordları <b>−6</b>, köyün refahı çöker ve günlerce gönüllü vermez, namın <b>−6</b>, <b>yağmacı damgası +{1}</b> (gönüllü ve paralı asker pahalanır, lordlar yüz vermez). {2}": "lords of {0} <b>−6</b>, the village's prosperity collapses and it sends no volunteers for days, renown <b>−6</b>, <b>raider's mark +{1}</b> (volunteers and mercenaries cost more, lords turn their backs). {2}",
