  "{0}{1} dinar/gün</b> ({2} asker).{3} <br>Garnizon grup kapasitenden düşmez ama maaşını sen ödersin; düşman kuşatması bu sayıya bakar.": "{0}{1} denars/day</b> ({2} troops).{3} <br>A garrison does not count against your party capacity, but you pay its wages; an enemy siege looks at this number.",
