  "Öde ve Kurtul": "Pay and go free",
  "Ödemeyi peşin isteme. Peşin ödeyen adam iki kere ödemiş sayılır.": "Don't ask to be paid up front. A man who pays in advance has paid twice.",
  "Ödül:": "Reward:",
  "Ölen askerin yaralı kurtulma şansı %{0}": "{0}% chance a fallen soldier survives wounded",
  "Öyle davran. Yanılırsak da zararı yok.": "Behave as though he is. No harm done if we're wrong.",
  "Öyleyse iki şey ödesinler: vergi ve özür.": "Then let them pay twice: the tax and an apology.",
  "Öğle": "Noon",
  "Öğrenme Hızı: x{0} | Odak: {1}/5": "Learning rate: x{0} | Focus: {1}/5",
  "Ünlü": "Renowned",
  "Üstlendiğin bir görev yok. Bir şehrin ya da kalenin Lordlar Salonuna git, bir soyluyla konuş ve \"Bana bir iş var mı?\" de.": "You have taken on no quest. Go to the Lords' Hall of a town or castle, speak to a noble and say \"Is there work for me?\".",
  "Üç gün marangozluk ister; kule surda ikinci bir gedik açar, savunanın avantajı erir (+%15).": "Three days of carpentry; the tower opens a second breach and the defenders' edge melts away (+15%).",
  "Üç mü? Felaket. Savaş ilan et, seferde içeriz.": "Three? A disaster. Declare war; we'll drink on campaign.",
  "ölçülmedi": "not measured",
