  "İyi Kalpli": "Good-Natured",
  "İyi. Umarım bu sohbette işime yaramaz.": "Good. I hope it won't come in handy during this conversation.",
  "İçeride ne olduğunu ancak girince öğrenirsin.": "You will only learn what is inside once you go in.",
  "İçeride senden önce gelenlerin izinden başka bir şey yok.": "Inside there is nothing but the tracks of those who came before you.",
  "İçeriden çıkan sesi duyduğunda geç kalmıştın — burası boş değilmiş.": "By the time you heard the sound from inside it was too late — this place wasn't empty.",
  "İş var, para var. Benim payım büyük ama seninki de var.": "There's work and there's money. My share is the larger, but you have one too.",
  "İşe Al: {0} kişi ({1} Dinar)": "Hire: {0} men ({1} denars)",
  "İşi Sor": "Ask about work",
  "İşini bitir de git. Akşam bir asmam var, geç kalmak istemem.": "Say your piece and go. I have a hanging this evening and I'd rather not be late.",
  "İşletme": "Enterprise",
  "İşte adam dediğin! Hizmetkâr, iyi şaraptan getir — hayır, çok iyi olanından.": "Now there's a man! Servant, bring the good wine — no, the very good one.",
  "ıska": "miss",
  "Şafak": "Dawn",
  "Şafak duasını hiç kaçırmadığı söylenir.": "They say she has never missed the dawn prayer.",
  "Şafak sökerken sınırı geçtiniz. Arkanızda bağıran bir kale kaldı.": "You crossed the border at daybreak. Behind you, a castle was still shouting.",
  "Şairler beni yeterince yazmıyor. Birine para verdim, üçüncü kıtada beni unuttu.": "The poets don't write enough about me. I paid one, and by the third stanza he had forgotten me.",
  "Şanslısın! Fırsatını bulup fidye ödemeden kaçmayı başardın!": "Lucky you! You found your moment and got away without paying a ransom!",
  "Şarap bitince savaş başlar derler. Ben o yüzden mahzeni büyüttüm — barış budur.": "They say war begins when the wine runs out. That's why I enlarged the cellar — that is peace.",
  "Şehir": "Town",
  "Şeref: eylemlerinin ikinci itibar ekseni (−100..100)": "Honor: the second axis of your reputation (−100..100)",
