  "Şu zavallılara bakın... {0} sen soldan vur, {1} sen arkadan dolaş!": "Look at these poor wretches... {0}, hit them from the left; {1}, come round behind!",
  "Şu üstündekine kılık mı denir? Konuş bakalım, kısa tut.": "Do you call that an outfit? Speak, then — keep it short.",
  "Şuna bak, tam sana göre. Kaybedersen de güzel bir hikâye olur.": "Look at this — perfect for you. And if you lose, it makes a good story.",
  "Şölen daveti": "Feast invitation",
  "Şölen için {0} birim yüksek kalite yemek (et/peynir) gerek. Sende {1} var.": "A feast needs {0} units of fine food (meat/cheese). You have {1}.",
  "Şölen için {0} dinar gerek.": "A feast needs {0} denars.",
  "Şölen salonu doldu, kadehler kalktı.": "The feast hall filled and the cups went up.",
  "Şölenin başladı! {0} bütün soyluları geldi. Her biriyle +5 ilişki, +15 nam.": "Your feast has begun! Every noble of {0} has come.\n+5 relation with each, +15 renown.",
  "— kendi kazanmana yatırırsın, oran tur ilerledikçe katlanır.": "— you bet on yourself, and the odds compound as the rounds go by.",
