  "🏆 Turnuva Alanı</h3><p>Şu anda bu şehirde turnuva düzenlenmiyor.": "🏆 Tournament ground</h3><p>No tournament is being held in this town at the moment.",
  "🏆 Turnuva zaferini ona ithaf et (+18)": "🏆 Dedicate your tournament victory to her (+18)",
  "🏆 Turnuvaya Katıl": "🏆 Enter the Tournament",
  "🏆 {0} Turnuvası!</h3> <p><b>{1} tur</b> — her turda kuradan <b>rastgele bir ekipman</b> çıkar; kiminde hedef küçülür, kiminde büyür.</p> <p>Şampiyonluk ödülü: <b>500 Dinar</b> ve <b>+20 Nam</b>. Elenirsen turnuva sona erer.": "🏆 The {0} tournament!</h3> <p><b>{1} rounds</b> — each round the draw hands you <b>a random weapon</b>; with some the target shrinks, with others it grows.</p> <p>The champion's prize: <b>500 denars</b> and <b>+20 renown</b>. Go out and the tournament is over for you.",
  "🏆 Şampiyon": "🏆 Champion",
  "🏇 Kaçırma</h3> <p>Gece yarısı, arka kapı, iki at. Drahoma yok, tören yok.": "🏇 Elopement</h3> <p>Midnight, a back door, two horses. No dowry, no ceremony.",
