  "🏰 {0} Kuşatması</h3> <p>Garnizonda tahmini <b>{1}</b> asker var. Kampı kurunca ordun kapıda bekler: hazırlık bitene kadar zaman akar, {2} lordları kuşatmayı yarmaya gelebilir.": "🏰 The siege of {0}</h3> <p>The garrison is reckoned at <b>{1}</b> troops. Once you make camp your army waits at the gate: time runs until the preparations are done, and lords of {2} may ride out to break the siege.",
