  "🔥 {0} Yağması</h3> <p>Köy milisi tahminen <b>{1}</b> kişi. Dağıtırsan ambarı boşaltmak <b>{2} saniye</b> sürer — o sürede kıpırdayamazsın ve dumanı gören {3} lordları üstüne yürür. Yetişirlerse ganimet yok.": "🔥 The sack of {0}</h3> <p>The village militia is reckoned at <b>{1}</b> men. Once you scatter them, emptying the granary takes <b>{2} seconds</b> — you cannot move in that time, and lords of {3} who see the smoke will ride at you. If they arrive first, there is no plunder.",
