  " title=\"Harcanmamış puanların var — karakter ekranına git (C)\">✨ {0}": " title=\"You have unspent points — open the character screen (C)\">✨ {0}",
  "<button id=\"btn-points\" onclick=\"Game.showScreen('character')\"": "<button id=\"btn-points\" onclick=\"Game.showScreen('character')\"",
  "Adamları say derseniz sayarım ama gerek yok, hepsi yatacak.": "I can count them if you want, commander, but no need — they're all going down.",
  "Aç karnına ölmek var mı, o da ayrı zulüm.": "Dying on an empty stomach — now that's a cruelty of its own.",
  "Bak şu adamın kılıcına. Benimki tırpandan bozma.": "Look at that man's sword. Mine used to be a scythe.",
  "Bir gün de kimseyle karşılaşmadan yürüsek.": "One day I'd like to march without running into anybody.",
  "Borcunu ödemeyen komutanın ardından kılıç sallamak zor iş.": "It's hard work swinging a sword for a commander who doesn't pay up.",
  "Bugün bedava dövüşüyorum. Yarın hesabı konuşuruz komutanım.": "I'm fighting for free today. We'll talk about the bill tomorrow, commander.",
  "Bunlar da bir yerden çıkıyor. Fabrikaları mı var?": "These lot keep coming from somewhere. Do they have a factory?",
  "Bunlar mı? Kahvaltıdan önce toplarız.": "These? We'll clean them up before breakfast.",
  "Dövüşürüm de önce bir ekmek olsa? İki gündür kayış yiyorum.": "I'll fight, but could I have some bread first? I've been chewing my belt for two days.",
  "Ganimeti şimdiden paylaşalım, sonra tartışmayalım.": "Let's split the loot now so we don't argue later.",
  "Karnım gurulduyor, düşman duyup yerimizi buluyor.": "My stomach's growling so loud the enemy will find us by sound.",
  "Komutanım, sen izle. Biz hallederiz.": "Just watch, commander. We'll handle it.",
  "Komutanım, ölürsem maaşımı anneme verirsiniz değil mi? ...Vermezsiniz.": "Commander, if I fall you'll give my wages to my mother, won't you? ...You won't.",
  "Maaşı alamadık ama ölmeye ilk biz gidiyoruz, güzel düzen.": "We haven't been paid, but we're first in line to die. Lovely arrangement.",
  "Nereden geldim buraya, anamın evi sıcacıktı...": "What am I doing here? My mother's house was so warm...",
  "Sayarım ha: onlar çok, biz az. Matematik bu, kabahat bende değil.": "Let me count: they're many, we're few. That's mathematics, don't blame me.",
  "Yine mi? Daha dün mızrağımı temizlemiştim.": "Again? I only cleaned my spear yesterday.",
  "Şimdi kaçsak kimse fark etmez bence. Ben fark etmem mesela.": "If we ran now I don't think anyone would notice. I certainly wouldn't.",
