  "Çelik Baldırlık": "Steel Greaves",
  "🛡️ {0}, {1} çetesini dağıttı.": "🛡️ {0} scattered the {1} band.",
  "☠️ {0}, {1} ordusunu bozguna uğrattı.": "☠️ {0} routed {1}'s army.",
