  "Aranan Adam": "Sought-After",
  "20 görev tamamladın.": "You completed 20 quests.",
  "Diyarın Hizmetkârı": "Servant of the Realm",
  "50 görev tamamladın.": "You completed 50 quests.",
  "Bir Dalda Usta": "Master of a Craft",
  "Bir yeterlilikte 5. kademeye ulaştın.": "You reached level 5 in a proficiency.",
  "Çok Kolay": "Very Easy",
  "Çok Zor": "Very Hard",
  "Aldığın hasar %55 az, verdiğin %50 fazla": "You take 55% less damage and deal 50% more",
  "Aldığın hasar %110 fazla, verdiğin %30 az": "You take 110% more damage and deal 30% less",
  "Borç Tahsildarı": "Debt Collector",
  "Üç soylu bana borçlu, hiçbiri ödemiyor. Sözle bastıramadım, belki sen bastırırsın. Üçünü de bul, borcu hatırlat — kimin ne kadar utandığı beni ilgilendirmez.": "Three nobles owe me and none will pay. I could not press them with words; perhaps you can. Find all three and remind them of the debt — how ashamed each one feels is no concern of mine.",
  "Borçlu lordları sırayla ziyaret et ve tahsilatı hatırlat — <b>{0}/{1}</b>.": "Visit the indebted lords one by one and remind them to pay — <b>{0}/{1}</b>.",
  "{0} borcunu hatırlayınca suratı asıldı ama ödedi. ({1}/{2})": "{0}'s face soured at the reminder, but they paid. ({1}/{2})",
  "Kaçak Birlik": "Rogue Company",
  "Bayrağımı taşıyan bir birlik firar etti, şimdi kendi hesabına yağma yapıyor. Bunu duyurmam yasak — utanç krallığa yeter. Bul onları, sessizce hallet.": "A company under my banner deserted and now plunders on its own account. I am forbidden to announce it — the shame would fall on the whole kingdom. Find them and deal with it quietly.",
  "Haritada <b>{0}</b> birliğini bul ve dağıt; aşağıdaki yer birliğin şu an dolaştığı civardır — birlik gezer, işaret de onunla kayar.": "Find and scatter the <b>{0}</b> company on the map; the place below is where it roams now — the band moves, and the marker drifts with it.",
  "Gölgedeki Ferman": "The Shadowed Writ",
  "{0} surlarının içinde bize yazılmış bir ferman var, kimin elinde olduğunu biliyorum. Sokul, al, sıvış. Yakalanırsan seni tanımam — ama fermanı getirirsen krallık senin adını anar.": "Within the walls of {0} lies a writ meant for us, and I know whose hands hold it. Slip in, take it, slip out. If you are caught I will not know you — but bring the writ back and the kingdom will remember your name.",
  "<b>{0}</b> surlarına sokul ve fermanı ele geçir.": "Slip into the walls of <b>{0}</b> and seize the writ.",
  "Ferman elinde — sınırı geçip <b>{0}</b> dön, izini kaybettir.": "The writ is in hand — cross the border back to <b>{0}</b> and shake off your trail.",
  "Ferman elinde. Şimdi sınırı sağ salim geçmen lazım.": "The writ is in hand. Now you must cross the border in one piece.",
  "Tüccar Kervanı": "Merchant Convoy",
  "Kervanım <b>{0}</b> mal götürecek. Yolun ortasında pusu kurulduğunu duydum ama nerede bilmiyorum. Kervanla git, pusuya düşerlerse kurtar, sonunda kervanı sağ salim teslim et.": "My caravan is to carry goods to <b>{0}</b>. I have heard an ambush is laid somewhere along the road, but not where. Ride with the caravan, save it if they are ambushed, and deliver it safely in the end.",
  "Kervan pusuya düştü — saldıranları dağıt.": "The caravan is ambushed — scatter the attackers.",
  "Kervanla birlikte <b>{0}</b> doğru yol al; yolda pusu olabilir.": "Travel toward <b>{0}</b> with the caravan; there may be an ambush on the way.",
  "Kervan Baskıncıları": "Caravan Raiders",
  "Kervanın önü kesildi! Silaha sarıl.": "The caravan is cut off! Take up arms.",
  "Baskıncılar dağıtıldı, kervan yoluna devam ediyor.": "The raiders are scattered; the caravan moves on.",
  "Kuşatma Erzakı": "Siege Provisions",
  "{0} kuşatma altında, ambarları tükeniyor. <b>{1} birim yemek</b> bul, muhasara hattını yarıp içeri sok. Çabuk ol, açlık kılıçtan hızlı öldürür.": "{0} is under siege and its granaries are running dry. Find <b>{1} units of food</b>, break through the siege line and get it inside. Be quick — hunger kills faster than the sword.",
  "<b>{0}</b> gir, çantanda <b>{1}/{2}</b> birim yemek olsun.": "Enter <b>{0}</b> with <b>{1}/{2}</b> units of food in your pack.",
  "Yeterince erzak yok. ({0}/{1})": "Not enough provisions. ({0}/{1})",
  "Rehine Değişimi": "Hostage Exchange",
  "Düşman elimizdeki esirleri istiyor, karşılığında bizim adamlarımızı serbest bırakacaklar. Soylu olmayan <b>{0} esiri</b> <b>{1}</b> kapısına götür ve değiş tokuşu yap.": "The enemy wants the prisoners we hold and will free our own men in return. Take <b>{0} common prisoners</b> to the gates of <b>{1}</b> and make the exchange.",
  "Soylu olmayan esirlerle <b>{0}</b> gir — <b>{1}/{2}</b>.": "Enter <b>{0}</b> with common prisoners — <b>{1}/{2}</b>.",
  "Sisteki Nokta": "The Point in the Mist",
  "\"{0} yakınlarında, sisin hiç dağılmadığı bir nokta var diyorlar. Oraya giden dönmüş ama eskisi gibi konuşmuyor artık.<br><br> Ben yaşlıyım, gidemem. Sen git — ne olduğunu öğren, dönebilirsen anlat.\"": "\"They say there is a point near {0} where the mist never lifts. One who went there came back, but no longer speaks as they once did.<br><br> I am old and cannot go. You go — learn what it is, and if you return, tell me.\"",
  "<b>{0}</b> civarını araştır — sisin dağılmadığı yeri bul.": "Search around <b>{0}</b> — find the place where the mist will not lift.",
  "Sisin içinden şekiller çıktı — üstüne git, ne olduklarını öğren.": "Shapes came out of the mist — go at them, learn what they are.",
  "Nokta sustu. Dönüp anlatman gerek.": "The point fell silent. You must return and tell of it.",
  "Sisteki Gölgeler": "Shadows in the Mist",
  "Sis kalınlaşıyor. İçinden insan biçimleri sıyrılıp geliyor.": "The mist thickens. Human shapes are peeling out of it.",
  "Gölgeler dağılınca sis de dağıldı, geriye ne kırık bir mühür ne de bir iz kaldı — sadece anlatacak bir hikaye.": "As the shadows scattered the mist lifted too, and neither a broken seal nor a trace remained — only a story to tell.",
  "🖥️ Tam ekran için <kbd>F11</kbd>": "🖥️ Fullscreen with <kbd>F11</kbd>",
