  "WebGL harita çizici başlatılamadı — Canvas2D ile devam": "The WebGL map renderer could not start — continuing with Canvas2D",
  "Cihaza göre: ekran kartı varsa harita ve savaş WebGL ile, keskin ve ekranın piksel yoğunluğunda çizilir; yoksa Canvas'a döner. Şu an: {0}.": "By device: with a graphics card the map and battles are drawn through WebGL, sharp at the screen's pixel density; otherwise it falls back to Canvas. Now: {0}.",
  "Diğer değerler": "More stats",
  "Erzak, silah ve zırh al-sat": "Buy and sell food, weapons and armour",
