  "Saçını değiştir": "Change your hair",
  "Saç: {0}": "Hair: {0}",
  "Saç topuzu": "Bun",
  "\"<b>{0}</b> yolda kaçırıldı. Adamlarım izi bir haydut inine kadar sürdü — kabaca <b>{1} kişi</b>.<br><br> Yerini haritana işaretledim. İstersen sessizce sız, istersen ordunla bas; yeter ki onu sağ çıkar.\"": "\"<b>{0}</b> was taken on the road. My men tracked them to a bandit lair — roughly <b>{1} men</b>.<br><br> I have marked it on your map. Sneak in or storm it with your army, as you like; just bring her out alive.\"",
  "\"Oğlum <b>{0}</b> av dönüşü haydutlara esir düştü. Bir inde tutuyorlar — kabaca <b>{1} kişi</b>.<br><br> Yerini haritana işaretledim. Onu bana geri getir; bunun karşılığını ömrüm boyunca unutmam.\"": "\"My son <b>{0}</b> was captured by bandits on his way back from the hunt. They keep him in a lair — roughly <b>{1} men</b>.<br><br> I have marked it on your map. Bring him back to me; I will not forget it as long as I live.\"",
  "<b>{0}</b> işaretli ☠️ <b>Haydut İni</b>nde tutuluyor: sız, iplerini çöz ve çıkışa kadar getir — ya da ini ordunla bas": "<b>{0}</b> is held in the marked ☠️ <b>Bandit Lair</b>: sneak in, cut the ropes and lead them to the exit — or storm the lair with your army",
  "<b>{0}</b> kurtarıldı — lorda haber ver.": "<b>{0}</b> is free — tell the lord.",
  "Sessiz ol. Eğilirsen daha az görünürsün.": "Keep quiet. Crouching makes you harder to see.",
