  "Kapı kilitli!": "The door is locked!",
  "Uyandı": "Woke up",
  "Fark edildin! Alarm!": "You were spotted! Alarm!",
  "Atış iptal.": "Throw called off.",
  "Çık": "Come out",
  "Peşindeler! Yarım kaldı.": "They're on you! You had to stop.",
  "Diken tuzağı!": "Spike trap!",
  "Yarasalar havalandı!": "Bats took flight!",
  "Baygın": "Out cold",
  "Yaralandı": "Wounded",
  "Bayılt": "Knock out",
  "Sus işareti ver": "Signal to hush",
  "Çözüp kurtar": "Untie and free",
  "Tutsak başını salladı.": "The prisoner nodded.",
  "Tuzağı sök": "Disarm the trap",
  "Tuzak sökülüyor…": "Disarming the trap…",
  "Tuzak söküldü.": "Trap disarmed.",
  "Sandığı aç": "Open the chest",
  "Açılıyor…": "Opening…",
  "Ara": "Search",
  "Aranıyor…": "Searching…",
  "Kolu çek": "Pull the lever",
  "Saklan": "Hide",
  "Meşaleyi söndür": "Douse the torch",
  "Atları ürküt": "Spook the horses",
  "Kilidi zorla": "Force the lock",
  "Kilit zorlanıyor…": "Forcing the lock…",
  "Kilit gıcırdayarak açıldı.": "The lock gave way with a screech.",
  "Kafes açık": "Cage open",
  "Keseyi al": "Take the purse",
  "Kese alınıyor…": "Taking the purse…",
  "Kapaktan geç": "Go through the hatch",
  "Kapaktan geçiliyor…": "Going through the hatch…",
  "Pencereden geç": "Climb through the window",
  "Pencereden geçiliyor…": "Climbing through the window…",
  "İnden ayrıl": "Leave the lair",
  "Peşindeler!": "They're on you!",
  "Peşinde haydutlar varken hiçbir şeyle uğraşamazsın. Önce onlardan kurtul ya da uzaklaş.": "With bandits on your heels you can't stop for anything. Shake them off or get away first.",
  "Boş": "Empty",
  "+{0} çakıl taşı": "+{0} pebbles",
  "Şifalı ot (+{0} can)": "Healing herb (+{0} health)",
  "Şifalı ot": "Healing herb",
  "İnin kesesi senin!": "The lair's purse is yours!",
  "Samanın içine gömüldün. Yanına gelmedikçe seni göremezler.": "You burrowed into the hay. They can't see you unless they come right up to you.",
  "Kayanın gölgesine sindin. Yanına gelmedikçe seni göremezler.": "You shrank into the rock's shadow. They can't see you unless they come right up to you.",
  "Dolaba girdin. Kapağı açmadıkça seni göremezler.": "You slipped into the wardrobe. They can't see you unless they open it.",
  "Atacak taşın kalmadı. Çuvallarda, sandıklarda bulabilirsin.": "No pebbles left. Sacks and crates may have some.",
  "Atlar kişneyip ağılda deli gibi koşuşuyor!": "The horses neigh and bolt round the pen!",
  "Meşale söndü. Biri yakmaya gelecek.": "The torch is out. Someone will come to light it.",
  "Bayıltılıyor…": "Knocking out…",
  "İpler çözülüyor…": "Untying the ropes…",
  "Kurtarıldı": "Freed",
  "{0}: \"Sonunda! Beni buradan çıkar, çıkışa kadar peşindeyim.\"": "{0}: \"At last! Get me out of here, I'll stay right behind you to the exit.\"",
  "Tutsak peşine takıldı. Onu dışarı çıkar!": "The prisoner follows you. Get them out!",
  "Sandık tuzaklıymış!": "The chest was trapped!",
  "Kol çekiliyor…": "Pulling the lever…",
  "Taşlar gürültüyle yuvarlandı!": "The stones rumbled aside!",
  "Uyandı!": "Awake!",
  "Bir haydut yerde yatan arkadaşını buldu!": "A bandit found his mate on the floor!",
  "Meşaleyi yaktı": "Relit the torch",
  "Pusu! Tünel çöktü": "Ambush! The tunnel caved in",
  "Pusu! Kapı kapandı": "Ambush! The door slammed",
  "Pusu! İkişer ikişer saldırıyorlar, sakin ol.": "Ambush! They come two at a time, keep calm.",
  "Pusu! Askerlerin yanında.": "Ambush! Your soldiers are with you.",
  "Pusu bitti. Yol açıldı.": "The ambush is over. The way is open.",
  "Bu tutsak heyecanlı. Önce sus işareti ver, yoksa bağıracak.": "This prisoner is excited. Signal them to hush first, or they'll shout.",
  "Tutsak bağırdı: \"Buradayım! Kurtarın beni!\"": "The prisoner shouted: \"I'm here! Save me!\"",
  "Kurtarın!": "Help!",
  "Seni kaybettiler. Arıyorlar…": "They lost you. They're searching…",
  "Tık!": "Clack!",
  "ÇIKIŞ": "EXIT",
  "Saklanıyor · görünmez": "Hidden · unseen",
  "Eğilmiş · sessiz": "Crouched · quiet",
  "Koşuyor · gürültülü": "Running · loud",
  "Ayakta": "Standing",
  "suda": "in water",
  "Taş ({0})": "Stone ({0})",
  "İptal": "Cancel",
  "Reisin <b>kesesini</b> al": "Take the leader's <b>purse</b>",
  "<s>Kese</s> alındı": "<s>Purse</s> taken",
  "<b>Tutsakları</b> kurtar ({0}/{1})": "Free the <b>prisoners</b> ({0}/{1})",
  "Sonra <b>çıkışa</b> dön": "Then head back to the <b>exit</b>",
  "Alarm · {0} sn": "Alarm · {0} s",
  "Seni arıyorlar": "They're looking for you",
  "Etkileşim": "Interact",
  "Dinar": "Denars",
  "Tutsak": "Prisoners",
  "Çakıl": "Pebbles",
  "yürü": "walk",
  "koş": "run",
  "eğil": "crouch",
  "etkileşim": "interact",
  "taş at": "throw a pebble",
  "saldır": "attack",
  "duraklat": "pause",
  "Eğil": "Crouch",
  "Taş": "Stone",
  "Saldır": "Attack",
