  "Haydutlar ayıyla boğuşuyor!": "The bandits are grappling with the bear!",
  "Yüzerken bir şey atamazsın.": "You can't throw anything while swimming.",
  "Yüzerken dövüşemezsin.": "You can't fight while swimming.",
  "Köpeği bayılt": "Knock out the dog",
