  "Halatı kes": "Cut the rope",
  "Halat kesiliyor…": "Cutting the rope…",
  "Ayının kafesini aç": "Open the bear's cage",
  "Kafesin sürgüsü çekiliyor…": "Drawing the cage bolt…",
