  "Şişe dokun: çevir. Basılı tut: servis et. Kazana dokun: karıştır. Kabarcıklara bak: ufak ufak kaynasın.": "Tap a skewer: turn it. Hold it: serve it. Tap the pot: stir. Watch the bubbles: keep it at a gentle simmer.",
  "Şişe tıkla: çevir. Basılı tut: servis et. Kazana tıkla: karıştır. Kabarcıklara bak: ufak ufak kaynasın.": "Click a skewer: turn it. Hold it: serve it. Click the pot: stir. Watch the bubbles: keep it at a gentle simmer.",
  "🪵 Odun at": "🪵 Add wood",
