  "Sapma": "Off line",
  "Parmağınla sağa sola sürterek biç. Yukarı-aşağı kaydırarak testereyi eğ: damarlar testereyi kendine çeker, kesik kurşun kalem çizgisinde kalsın.": "Saw by rubbing your finger left and right. Slide up and down to lean the saw: the grain pulls the saw its way; keep the cut on the pencil line.",
  "Fareyle basılı tutup sağa sola sürterek biç (ya da Boşluk). Yukarı-aşağı sürükleyerek testereyi eğ: damarlar testereyi kendine çeker, kesik kurşun kalem çizgisinde kalsın.": "Hold the mouse and rub left and right to saw (or Space). Drag up and down to lean the saw: the grain pulls the saw its way; keep the cut on the pencil line.",
  "Rende": "Plane",
  "Lif kalkması": "Torn grain",
  "Parmağını bas ve sağa sola sür: rende yüksek yerleri alır. Okların yönünde sür, kesik çizgi altın olunca orayı bırak.": "Press your finger and slide left and right: the plane takes the high spots. Slide the way the arrows point; leave a spot once its dashed line turns gold.",
  "Basılı tutup sağa sola sürükle (ya da Boşluk + ← →): rende yüksek yerleri alır. Okların yönünde sür, kesik çizgi altın olunca orayı bırak.": "Hold and drag left and right (or Space + ← →): the plane takes the high spots. Slide the way the arrows point; leave a spot once its dashed line turns gold.",
  "Vazgeçersen vardiyanın parası ödenmez; bugün bu handa yine çalışamazsın.": "If you give up the shift isn't paid, and you can't work at this inn again today.",
  "Vazgeçersen kereste sana kalır; kira ödenmiştir.": "If you give up you keep the timber; the rent is paid.",
