  "İş tutmadı; artan tahtadan {0} çıkardın, çantanda.": "It didn't come out; from the leftover wood you made a {0}, it's in your bag.",
  "Tahta odun oldu. {0} kereste kurtardın.": "The wood is firewood now. You saved {0} timber.",
