  "Mutfak": "Kitchen",
  "Kereste": "Timber",
  "Biçilmeye hazır meşe ve çam kalası. Marangozun ekmeği.": "Oak and pine beams ready for the saw. A carpenter's bread and butter.",
  "Tabure": "Stool",
  "Üç ayaklı, sağlam bir tabure. Her hanın köşesinde bir tane bulunur.": "A sturdy three-legged stool. Every inn has one in the corner.",
  "Ahşap Sandık": "Wooden Chest",
  "Demir köşebentli, kilitli bir sandık. Çeyiz de saklar, ganimet de.": "A locking chest with iron corners. It keeps a dowry as well as loot.",
  "Araba Tekerleği": "Cart Wheel",
  "Göbeği, parmakları ve demir çemberiyle bir araba tekerleği. Yolda kalan kervancının kurtarıcısı.": "A cart wheel with its hub, spokes and iron tyre. The rescue of a caravaneer stuck on the road.",
  "Meşe Masa": "Oak Table",
  "Tek parça meşe tablalı, ağır bir masa. Lord salonlarına layık.": "A heavy table with a one-piece oak top. Fit for a lord's hall.",
  "Kereste biç, rendele, eşya yap": "Saw timber, plane it, make goods",
  "Mutfakta çalış, yevmiye al": "Work in the kitchen for a day wage",
  "Rendelenen": "Planed",
  "🧰 Başka meslek": "🧰 Another trade",
  "Deneme: para, XP ve zaman yok.": "Practice: no pay, XP or time.",
  "Deneme: kereste harcanmaz; eşya, XP ve zaman yok.": "Practice: no timber used; no item, XP or time.",
  "Vardiya bitti: {0} dinar kazanırdın.": "The shift is over: you would have earned {0} dinars.",
  "İş tutmadı: {0} olurdu.": "The work didn't come out: it would have been a {0}.",
  "Tahta odun oldu.": "The board turned to firewood.",
  "Deneme mutfağı": "Practice kitchen",
  "Deneme tezgâhı": "Practice bench",
  "Zanaat": "Crafts",
  "Meslekler": "Trades",
  "Oyuna başlamadan bir zanaatı dene: malzeme harcanmaz; eşya, para, XP ve zaman yok.": "Try a trade before starting the game: no materials used; no item, money, XP or time.",
  "Dene": "Try",
  "Marangozluk Dene": "Try Carpentry",
  "Her parça açık, kereste harcanmaz; eşya, XP ve zaman yok.": "Every piece is open, no timber used; no item, XP or time.",
  "Ocakta demir döv, su ver, taşta bile.": "Forge iron at the hearth, quench it, sharpen it on the stone.",
  "Tahtayı damarına karşı biç, kenarını rendele.": "Saw the board against its grain and plane its edge.",
  "Han mutfağında bir vardiya: şişler ve çorba kazanı.": "A shift in the inn kitchen: the skewers and the soup pot.",
  "Tavı kaçtı: çelik fazla ısınıp sertliğini yitirdi! Orası mavi kaldı, artık en fazla yarıya kadar bilenir. Bir yerde durma.": "The temper is lost: the steel overheated and went soft! That spot stays blue and will only sharpen halfway now. Don't stay in one place.",
  "Çelik ısınıyor: ağzın üstü sarardı. Bıçağı kaydır!": "The steel is heating up: above the edge it's turning yellow. Slide the blade on!",
  "Her puan yakın dövüş saldırına +1 ekler. Kılıç Ustalığı ve Örs yetenek dallarını açar.": "Each point adds +1 to your melee attack. Unlocks the Weapon Mastery and Anvil perk branches.",
  "Haritada daha hızlı yol alırsın; savaşta daha çabuk koşar, atını daha hızlı sürersin. Süvari ve Okçu dalını açar.": "You travel faster on the map; in battle you run quicker and ride your horse faster. Unlocks the Cavalry & Archery branch.",
  "Haritada daha uzağı görürsün: her puan +30 birim görüş. Sıhhiye ve Zindan ile İz Sürme dallarını açar.": "You see farther on the map: each point adds +30 units of sight. Unlocks the Medicine & Dungeon and Scouting branches.",
  "Her puan grubuna 3 asker daha sığdırır. Komuta ile Çapul ve Ticaret dallarını açar.": "Each point makes room for 3 more troops in your party. Unlocks the Command and Raiding & Trade branches.",
  "Her puan +5 en yüksek can; her iki puanda yaraların bir saat daha çabuk kapanır.": "Each point adds +5 max health; every two points heal your wounds an hour faster.",
  "Nitelikler ne işe yarar?": "What do attributes do?",
  "Hepsi 10'dan başlar. Seviye atladıkça puan dağıtırsın; puan hedefi yükseltir, nitelik o işe uygun oynadıkça hedefe yaklaşır.": "They all start at 10. You spend points as you level up; a point raises the target, and the attribute climbs toward it as you play in ways that suit it.",
  "Isıt": "Heat",
  "Körüğe bas: ocak beyazlaşır, demir ısınır.": "Press the bellows: the hearth glows white and the iron heats.",
  "Rengine bak": "Read its colour",
  "Turuncu-sarıyken örse al; koyu kırmızı soğuk, beyaz yanar.": "Take it to the anvil at orange-yellow; dark red is cold, white burns.",
  "Soğuk": "Cold",
  "Dövülür": "Ready to forge",
  "Yanar": "Burns",
  "Döv": "Hammer",
  "Çekici demire getir; basılı tut, bırak. Ne kadar tutarsan o kadar sert.": "Bring the hammer over the iron; hold, then release. The longer you hold, the harder it strikes.",
  "Çizgiye kadar": "Down to the line",
  "Kesik çizgiye inen yer altın olur. Çizgiyi geçme.": "Where it reaches the dashed line it turns gold. Don't go past the line.",
  "Kalın": "Too thick",
  "Fazla": "Too far",
  "Soğuyunca ısıt": "Reheat when it cools",
  "Kızıllık gidince ocağa geri koy: soğuk demir çatlar.": "When the glow fades, put it back in the hearth: cold iron cracks.",
  "Demir baştan uca kiraz-turuncuyken Su ver'e bas.": "Press Quench while the iron is cherry-orange end to end.",
  "Sonuç": "The result",
  "İyi iş istediğin kademeyi verir, zayıf iş bir altını, kötü iş çatlar.": "Good work gives the tier you wanted, weak work the one below, bad work cracks.",
  "Usta işi": "Masterwork",
  "Desenli parça Demircilik 9 ve haydut madeninden pota çeliği ister.": "A patterned piece needs Smithing 9 and crucible steel from the bandit mine.",
  "Dövülmüş bir parçayı ocağa atarsan demirinin yarısı geri döner.": "Throw a forged piece into the hearth and half its iron comes back.",
  "Taşa bas": "Press to the stone",
  "Basılı tut ve sağa sola sür: ağzın her yeri bilenir.": "Hold and slide left and right: every part of the edge gets ground.",
  "Açıyı tut": "Hold the angle",
  "Yukarı-aşağı sürükle. Bol, uzun, parlak kıvılcım: açı doğru.": "Drag up and down. Plenty of long, bright sparks: the angle is right.",
  "Ağzı beyazlat": "Bring the edge to white",
  "Kör yer koyu gri, keskin yer bembeyaz. Hepsini beyazlat.": "A dull spot is dark grey, a sharp one bright white. Make it all white.",
